#include "stdlib/blas/base/shared.h"
#include "stdlib/blas/base/zrotg.h"
#include "stdlib/blas/base/zrotg_fortran.h"
#include "stdlib/complex/float64/ctor.h"
#include "stdlib/complex/float64/real.h"
#include "stdlib/complex/float64/imag.h"
#include "stdlib/strided/base/min_view_buffer_index.h"
#include "stdlib/strided/base/stride2offset.h"


/**
* Constructs a Givens plane rotation.
*
* @param a        first input value
* @param b        second input value
* @param Out      output array
* @param strideOut  output stride length
*/
void API_SUFFIX( c_zrotg )( const stdlib_complex128_t a, const stdlib_complex128_t b, double *Out, const CBLAS_INT strideOut ) {
	CBLAS_INT relOffset;
	stdlib_complex128_t ta;
	stdlib_complex128_t tb;
	stdlib_complex128_t ts;
	double c;

	relOffset = stdlib_strided_stride2offset( 5, strideOut );

	ta = a;
	tb = b;

	zrotg( &ta, &tb, &c, &ts );

	Out[ relOffset ] = stdlib_complex128_real( ta );  // real(r)
	Out[ relOffset + strideOut ] = stdlib_complex128_imag( ta );  // imag(r)
	Out[ relOffset + ( 2 * strideOut ) ] = c;
	Out[ relOffset + ( 3 * strideOut ) ] = stdlib_complex128_real( ts );  // real(s)
	Out[ relOffset + ( 4 * strideOut ) ] = stdlib_complex128_imag( ts );  // imag(s)
}

/**
* Constructs a Givens plane rotation using alternative indexing semantics.
*
* @param a        first input value
* @param b        second input value
* @param Out      output array
* @param strideOut  output stride length
* @param offsetOut  starting index for `Out`
*/
void API_SUFFIX( c_zrotg_assign )( const stdlib_complex128_t a, const stdlib_complex128_t b, double *Out, const CBLAS_INT strideOut, const CBLAS_INT offsetOut ) {
	CBLAS_INT minIndex;
	CBLAS_INT relOffset;
	stdlib_complex128_t ta;
	stdlib_complex128_t tb;
	stdlib_complex128_t ts;
	double c;

	minIndex = stdlib_strided_min_view_buffer_index( 5, strideOut, offsetOut );
	Out += minIndex;

	relOffset = offsetOut - minIndex;

	ta = a;
	tb = b;

	zrotg( &ta, &tb, &c, &ts );

	Out[ relOffset ] = stdlib_complex128_real( ta );  // real(r)
	Out[ relOffset + strideOut ] = stdlib_complex128_imag( ta );  // imag(r)
	Out[ relOffset + ( 2 * strideOut ) ] = c;
	Out[ relOffset + ( 3 * strideOut ) ] = stdlib_complex128_real( ts );  // real(s)
	Out[ relOffset + ( 4 * strideOut ) ] = stdlib_complex128_imag( ts );  // imag(s)
}
